// ignore_for_file: type=lint   // ❌ every lint in this file, including
                                //    lints on code written next year

class Repo {
  // ✅ narrowest form: one line, one rule, and a reason a reviewer can check
  // ignore: avoid_dynamic_calls  -- payload shape is asserted in decode()
  String title(dynamic json) => json['title'] as String;

  // ❌ silences `dart analyze`, and `dart compile` still fails on this line:
  //    the analyze step goes green in front of a build that cannot succeed
  // ignore: invalid_assignment
  final int count = 'seven';
}

void refresh(Repo repo) {
  // The trailing form covers only the line it sits on.
  repo.reload(); // ignore: unawaited_futures -- fire and forget, logs inside
}

// ── analysis_options.yaml ──
// analyzer:
//   exclude:
//     - "**/*.g.dart"       # right: generated, nobody reviews it
//     - "lib/legacy/**"     # wrong: hides errors too, not just lints
//   cannot-ignore:
//     - use_build_context_synchronously   # no comment can suppress this
// linter:
//   rules:
