// ── const is a rebuild boundary, not a style preference ──
class Header extends StatelessWidget {
  const Header({super.key});
  @override
  Widget build(BuildContext context) => const Text('Inbox');
}

class Screen extends StatefulWidget {
  const Screen({super.key});
  @override
  State<Screen> createState() => _ScreenState();  // no_logic_in_create_state:
}                                                 // this can run more than once

class _ScreenState extends State<Screen> {
  int count = 0;
  @override
  Widget build(BuildContext context) => Column(
    children: [
      Header(),        // ❌ a new instance each build -> the subtree rebuilds
      const Header(),  // ✅ canonicalised: identical widget, updateChild skips it
      Text('$count'),
    ],
  );
}
// flutter_lints enables prefer_const_constructors_in_immutables only.
// prefer_const_constructors is NOT in it — add it or you get none of the above.

// ── Comparisons that compile and are always false ──
final ids = <int>[1, 2, 3];
const raw = '2';
final a = ids.contains(raw);           // collection_methods_unrelated_type
final b = raw == 2;                    // unrelated_type_equality_checks
final c = ids.contains(int.parse(raw)); // ✅

// ── == without hashCode: the Set quietly keeps both ──
class Tag {
  const Tag(this.id);
  final String id;
  @override
  bool operator ==(Object other) => other is Tag && other.id == id;
  @override
  int get hashCode => id.hashCode;   // hash_and_equals: drop this line and
}                                    // {Tag('a'), Tag('a')} has two elements

// ── avoid_print: this line ships to users ──
print('auth response: $token');          // ❌ release build, logcat, forever
if (kDebugMode) log('auth ok', name: 'auth');  // ✅ dart:developer, debug only

// ── unawaited_futures: the error has nowhere to go ──
Future<void> save(BuildContext context) async {
  repo.write(draft);                     // ❌ throws into nothing, and the pop
  Navigator.of(context).pop();           //    races the write that is still open
}

Future<void> saveCorrectly(BuildContext context) async {
  await repo.write(draft);               // ✅ errors reach this frame's catch
  unawaited(analytics.log('saved'));     // ✅ deliberate, and it says so
  if (context.mounted) Navigator.of(context).pop();
}

// ── use_build_context_synchronously: the element may be gone ──
Future<void> submit(BuildContext context) async {
  final messenger = ScaffoldMessenger.of(context);  // ✅ read before the gap
  final result = await api.send(form);

  // ❌ ScaffoldMessenger.of(context) here can throw
  //    "Looking up a deactivated widget's ancestor is unsafe"
  messenger.showSnackBar(SnackBar(content: Text(result.message)));

  if (!context.mounted) return;          // ✅ the guard the lint recognises
  Navigator.of(context).pop();
}

// analysis_options.yaml
//   analyzer:
//     plugins:
//       - custom_lint
//
// CI needs its own step — `dart analyze` will not run any of this:
//   dart run custom_lint

PluginBase createPlugin() => _HouseLints();

class _HouseLints extends PluginBase {
  @override
  List<LintRule> getLintRules(CustomLintConfigs configs) => const [
        NoRepositoryInWidget(),
      ];
}

class NoRepositoryInWidget extends DartLintRule {
  const NoRepositoryInWidget() : super(code: _code);

  static const _code = LintCode(
    name: 'no_repository_in_widget',
    problemMessage: 'Widgets must not build a repository.',
    correctionMessage: 'Inject the notifier and call it from there.',
  );
  // No severity here on purpose: it lands as info, and analysis_options.yaml
  // promotes it like any other lint —  errors: { no_repository_in_widget: error }

  @override
  void run(
    CustomLintResolver resolver,
    ErrorReporter reporter,
    CustomLintContext context,
  ) {
    // Cheap bail-out first: this whole method re-runs on every keystroke.
    if (!resolver.path.contains('/ui/')) return;

    context.registry.addInstanceCreationExpression((node) {
      final type = node.staticType;
      if (type == null) return;
      // Resolved types, not spelling — this is the part grep cannot do.
      if (!type.getDisplayString().endsWith('Repository')) return;
      reporter.atNode(node, _code);
    });
  }
}

class UserApi {
  // The new name. The only implementation lives here.
  Future<User> parseUser(String body) async => User.fromJson(jsonDecode(body));

  @Deprecated('Use parseUser instead. Will be removed in 3.0.0.')
  Future<User> decodeUser(String body) => parseUser(body); // forwards, never copies
}

// ❌ No message: provide_deprecation_message flags it, and the caller learns the
//    member is dead without learning what replaced it.
class Legacy {
  @deprecated
  void sync() {}
}

// Consumer, in another package:
//   api.decodeUser(body);
//   ^^^ deprecated_member_use — a warning, and `dart analyze` exits non-zero.
//
// Inside your own package it is a different code, so you can quiet your own
// migration without touching what consumers see:
//
//   analyzer:
//     errors:
//       deprecated_member_use_from_same_package: ignore

