import 'package:meta/meta.dart';

@immutable
class Filter {
  const Filter(this.tags);
  final List<String> tags;  // ✅ satisfies must_be_immutable …
}                           // … and the list is still mutable. The check is shallow.

class CartModel extends ChangeNotifier {
  CartModel(this._sub);
  final StreamSubscription<void> _sub;

  @visibleForTesting
  int rawTotalCents = 0;

  @protected
  void recompute() {}

  @mustCallSuper
  @override
  void dispose() {
    _sub.cancel();
    super.dispose();
  }
}

class PromoCart extends CartModel {
  PromoCart(super.sub, this._timer);
  final Timer _timer;

  @override
  void dispose() {
    _timer.cancel();
    if (kDebugMode) super.dispose();  // ⚠️ must_call_super is SATISFIED here.
  }                                   // It checks the call exists, not that it runs.
}

// ── another library, e.g. lib/ui/checkout_page.dart ──
void checkout(CartModel cart) {
  cart.recompute();           // ⚠️ invalid_use_of_protected_member
  print(cart.rawTotalCents);  // ⚠️ invalid_use_of_visible_for_testing_member
}                             // Both are WARNINGS. This file compiles and ships.

