// The diff as it arrives: analyzer clean, one green widget test.
class _OrderPageState extends State<OrderPage> {
  final _note = TextEditingController();
  Order? _order;
  bool _loading = false;
  String? _error;          // blocking: _loading && _error != null is reachable.
                           // One sealed state makes it unrepresentable.

  @override
  void initState() {
    super.initState();
    _load();
  }
                           // blocking: no didUpdateWidget. Pushing a new
                           // orderId onto this route shows the old order forever.

  Future<void> _load() async {
    setState(() => _loading = true);
    final order = await OrderRepository().fetch(widget.orderId);
    //                  ^ suggestion: built here, so no test can replace it and
    //                    every retry allocates a fresh client.
    setState(() { _order = order; _loading = false; });
    // blocking: no catch anywhere. What does the user see with no network?
  }

  @override
  void dispose() {
    super.dispose();       // blocking: _note is never disposed.
  }

  @override
  Widget build(BuildContext context) {
    return Column(children: [
      Text(_order?.title ?? 'Loading…'),  // nit: user-visible, not in l10n.
      TextField(controller: _note),
    ]);
  }
}
